<?php
namespace App\Filament\Resources\AttributeValues;
use App\Filament\Resources\Concerns\AdminResource;use App\Filament\Resources\AttributeValues\Pages\ManageAttributeValues;use App\Models\AttributeValue;
use BackedEnum;use Filament\Actions\BulkActionGroup;use Filament\Actions\DeleteAction;use Filament\Actions\DeleteBulkAction;use Filament\Actions\EditAction;use Filament\Forms\Components\Select;use Filament\Forms\Components\TextInput;use Filament\Schemas\Schema;use Filament\Support\Icons\Heroicon;use Filament\Tables\Columns\TextColumn;use Filament\Tables\Table;
class AttributeValueResource extends AdminResource {protected static ?string $model=AttributeValue::class;protected static string $viewPermission='catalog.view';protected static ?string $managePermission='catalog.update';protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedListBullet;protected static ?string $navigationLabel='Giá trị thuộc tính';protected static string|\UnitEnum|null $navigationGroup='Sản phẩm';protected static ?int $navigationSort=80;public static function form(Schema $s):Schema{return $s->components([Select::make('attribute_id')->relationship('attribute','name')->searchable()->preload()->required(),TextInput::make('value')->label('Giá trị lưu')->required(),TextInput::make('label')->label('Nhãn hiển thị')->required(),TextInput::make('swatch_value')->label('Mã màu / swatch'),TextInput::make('sort_order')->label('Thứ tự')->numeric()->default(0)])->columns(2);}public static function table(Table $t):Table{return $t->columns([TextColumn::make('attribute_id')->label('ID thuộc tính'),TextColumn::make('value')->label('Giá trị')->searchable(),TextColumn::make('label')->label('Nhãn')->searchable(),TextColumn::make('swatch_value')->label('Swatch'),TextColumn::make('sort_order')->label('Thứ tự')])->recordActions([EditAction::make()->label('Sửa'),DeleteAction::make()->label('Xóa')])->toolbarActions([BulkActionGroup::make([DeleteBulkAction::make()])]);}public static function getPages():array{return ['index'=>ManageAttributeValues::route('/')];}}
